package net.civeira.phylax.feature.observe.observedalertrule.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRuleTriggerOptions;

class TriggerVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property trigger of observed alert rule ")
  void test_trigger_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> TriggerVO.tryFrom("_NEW_ISSUE_"));
    Assertions.assertEquals(ObservedAlertRuleTriggerOptions.NEW_ISSUE,
        TriggerVO.tryFrom("NEW_ISSUE").getTrigger());
    Assertions.assertThrows(ConstraintException.class, () -> TriggerVO.tryFrom(null));
    Assertions.assertEquals(ObservedAlertRuleTriggerOptions.NEW_ISSUE,
        TriggerVO.from(ObservedAlertRuleTriggerOptions.NEW_ISSUE).getTrigger());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> TriggerVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedAlertRuleTriggerOptions.NEW_ISSUE + "]",
        TriggerVO.from(ObservedAlertRuleTriggerOptions.NEW_ISSUE).toString());
  }
}
